import type { VaultRepositories } from "./db/repositories.js";
import type { VaultRecord } from "../../shared/types.js";

export type VaultRuntimeSessionState =
  | "starting"
  | "active"
  | "draining"
  | "drained"
  | "disposed";

export type VaultRuntimeProducerContext = {
  generation: number;
  signal: AbortSignal;
  vault: VaultRecord;
  repositories: VaultRepositories;
};

type ProducerEntry = {
  name: string;
  promise: Promise<unknown>;
};

let nextVaultRuntimeGeneration = 0;
let currentVaultRuntimeSession: VaultRuntimeSession | null = null;
const sessionChangeListeners = new Set<(
  previous: VaultRuntimeSession | null,
  next: VaultRuntimeSession | null,
) => void>();

export class VaultRuntimeAdmissionClosedError extends Error {
  constructor() {
    super("El runtime del vault ya no admite trabajo nuevo.");
    this.name = "VaultRuntimeAdmissionClosedError";
  }
}

export class VaultRuntimeSession {
  readonly generation: number;
  readonly vault: VaultRecord;
  readonly repositories: VaultRepositories;
  readonly abortController = new AbortController();

  #state: VaultRuntimeSessionState = "starting";
  #nextProducerId = 0;
  #producers = new Map<number, ProducerEntry>();
  #drainPromise: Promise<void> | null = null;
  #resolveDrain: (() => void) | null = null;

  constructor(vault: VaultRecord, repositories: VaultRepositories) {
    this.generation = ++nextVaultRuntimeGeneration;
    this.vault = vault;
    this.repositories = repositories;
  }

  get state() {
    return this.#state;
  }

  get signal() {
    return this.abortController.signal;
  }

  get acceptingWork() {
    return this.#state === "starting" || this.#state === "active";
  }

  get activeProducerCount() {
    return this.#producers.size;
  }

  activate() {
    if (this.#state !== "starting") {
      return false;
    }

    this.#state = "active";
    return true;
  }

  isCurrent() {
    return currentVaultRuntimeSession === this;
  }

  canPublish() {
    return this.isCurrent() && this.#state === "active" && !this.signal.aborted;
  }

  assertAcceptingWork() {
    if (!this.acceptingWork || this.signal.aborted) {
      throw new VaultRuntimeAdmissionClosedError();
    }
  }

  trackProducer<T>(name: string, producer: Promise<T>): Promise<T> {
    this.assertAcceptingWork();
    const producerId = ++this.#nextProducerId;
    const tracked = Promise.resolve(producer);
    this.#producers.set(producerId, { name, promise: tracked });

    void tracked.finally(() => {
      this.#producers.delete(producerId);
      this.#settleDrainIfReady();
    }).catch(() => undefined);

    return tracked;
  }

  runProducer<T>(
    name: string,
    producer: (context: VaultRuntimeProducerContext) => Promise<T>,
  ): Promise<T> {
    this.assertAcceptingWork();
    return this.trackProducer(name, producer({
      generation: this.generation,
      signal: this.signal,
      vault: this.vault,
      repositories: this.repositories,
    }));
  }

  beginDrain() {
    if (this.#state === "disposed" || this.#state === "drained") {
      return this.drain();
    }

    if (this.#state !== "draining") {
      this.#state = "draining";
      this.abortController.abort();
    }

    return this.drain();
  }

  drain() {
    if (this.#state === "drained" || this.#state === "disposed") {
      return Promise.resolve();
    }

    if (!this.#drainPromise) {
      this.#drainPromise = new Promise<void>((resolve) => {
        this.#resolveDrain = resolve;
      });
    }

    this.#settleDrainIfReady();
    return this.#drainPromise;
  }

  markDisposed() {
    if (this.#state === "disposed") return;
    if (this.#state !== "drained") {
      throw new Error("No se puede disponer una sesion que no termino de drenar.");
    }

    this.#state = "disposed";
  }

  describeActiveProducers() {
    return [...this.#producers.values()].map(({ name }) => name);
  }

  #settleDrainIfReady() {
    if (this.#state !== "draining" || this.#producers.size > 0) {
      return;
    }

    this.#state = "drained";
    const resolve = this.#resolveDrain;
    this.#resolveDrain = null;
    resolve?.();
  }
}

export function createVaultRuntimeSession(
  vault: VaultRecord,
  repositories: VaultRepositories,
) {
  return new VaultRuntimeSession(vault, repositories);
}

export function getCurrentVaultRuntimeSession() {
  return currentVaultRuntimeSession;
}

export function requireCurrentVaultRuntimeSession() {
  if (!currentVaultRuntimeSession) {
    throw new Error("No hay una sesion de runtime de vault activa.");
  }

  return currentVaultRuntimeSession;
}

export function setCurrentVaultRuntimeSession(session: VaultRuntimeSession | null) {
  const previous = currentVaultRuntimeSession;
  currentVaultRuntimeSession = session;
  if (previous !== session) {
    for (const listener of sessionChangeListeners) listener(previous, session);
  }
}

export function subscribeVaultRuntimeSessionChange(
  listener: (previous: VaultRuntimeSession | null, next: VaultRuntimeSession | null) => void,
) {
  sessionChangeListeners.add(listener);
  return () => sessionChangeListeners.delete(listener);
}

export function isVaultRuntimeGenerationCurrent(generation: number) {
  return currentVaultRuntimeSession?.generation === generation;
}
