import fs from "node:fs/promises";
import { createDevLogger } from "../../../../shared/dev-log.js";

const renameLogger = createDevLogger("backend.filesystem");
const RETRIABLE_RENAME_ERROR_CODES = new Set(["EPERM", "EBUSY"]);
const FILE_RETRY_DELAYS_MS = [60, 160, 320];
const DIRECTORY_RETRY_DELAYS_MS = [120, 260, 520, 1200, 2400];

type RenameFsApi = Pick<typeof fs, "rename" | "lstat">;

type RenameEndpointState =
  | {
      exists: false;
    }
  | {
      exists: true;
      kind: "directory" | "file" | "symlink" | "other";
      size: number | null;
      mtimeMs: number | null;
    }
  | {
      exists: null;
      errorCode: string | null;
      errorMessage: string;
    };

type RenamePathWithRetryOptions = {
  from: string;
  to: string;
  operation: string;
  itemId?: string | null;
  retryDelaysMs?: number[];
  fsApi?: RenameFsApi;
};

function wait(ms: number) {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

async function describePathState(targetPath: string, fsApi: RenameFsApi): Promise<RenameEndpointState> {
  try {
    const stats = await fsApi.lstat(targetPath);
    return {
      exists: true,
      kind: stats.isDirectory()
        ? "directory"
        : stats.isFile()
          ? "file"
          : stats.isSymbolicLink()
            ? "symlink"
            : "other",
      size: Number.isFinite(stats.size) ? stats.size : null,
      mtimeMs: Number.isFinite(stats.mtimeMs) ? Number(stats.mtimeMs.toFixed(3)) : null,
    };
  } catch (error) {
    const errorCode = (error as NodeJS.ErrnoException | undefined)?.code ?? null;
    if (errorCode === "ENOENT") {
      return { exists: false };
    }

    return {
      exists: null,
      errorCode,
      errorMessage: error instanceof Error ? error.message : String(error),
    };
  }
}

function buildMissingSourceError(sourcePath: string) {
  const error = new Error(`No existe la ruta origen actual: ${sourcePath}`) as NodeJS.ErrnoException;
  error.code = "ENOENT";
  return error;
}

function buildDestinationExistsError(targetPath: string) {
  const error = new Error(`Ya existe un item en destino: ${targetPath}`) as NodeJS.ErrnoException;
  error.code = "EEXIST";
  return error;
}

function isRetriableRenameError(error: unknown) {
  const code = (error as NodeJS.ErrnoException | undefined)?.code;
  return RETRIABLE_RENAME_ERROR_CODES.has(String(code || "").toUpperCase());
}

export async function renamePathWithRetry(options: RenamePathWithRetryOptions) {
  const {
    from,
    to,
    operation,
    itemId = null,
    retryDelaysMs,
    fsApi = fs,
  } = options;

  const initialSourceState = await describePathState(from, fsApi);
  const initialDestinationState = await describePathState(to, fsApi);

  if (initialSourceState.exists === false) {
    throw buildMissingSourceError(from);
  }

  if (initialDestinationState.exists === true) {
    throw buildDestinationExistsError(to);
  }

  const sourceKind = "kind" in initialSourceState ? initialSourceState.kind : "unknown";
  const effectiveRetryDelaysMs =
    Array.isArray(retryDelaysMs) && retryDelaysMs.length > 0
      ? retryDelaysMs
      : sourceKind === "directory"
        ? DIRECTORY_RETRY_DELAYS_MS
        : FILE_RETRY_DELAYS_MS;

  for (let attempt = 0; attempt <= effectiveRetryDelaysMs.length; attempt += 1) {
    try {
      await fsApi.rename(from, to);

      if (attempt > 0) {
        renameLogger.info(
          "items.rename.retry.succeeded",
          "El rename termino bien despues de un lock transitorio.",
          {
            operation,
            itemId,
            from,
            to,
            sourceKind,
            attempt: attempt + 1,
            maxAttempts: effectiveRetryDelaysMs.length + 1,
          },
        );
      }

      return;
    } catch (error) {
      const sourceState = await describePathState(from, fsApi);
      const destinationState = await describePathState(to, fsApi);
      const attemptNumber = attempt + 1;
      const maxAttempts = effectiveRetryDelaysMs.length + 1;
      const errorCode = (error as NodeJS.ErrnoException | undefined)?.code ?? null;

      if (destinationState.exists === true) {
        renameLogger.error(
          "items.rename.collision",
          "El rename fallo porque el destino ya existe al momento de ejecutar la operacion.",
          {
            operation,
            itemId,
            from,
            to,
            sourceKind,
            attempt: attemptNumber,
            maxAttempts,
            errorCode,
            sourceState,
            destinationState,
          },
        );
        throw buildDestinationExistsError(to);
      }

      if (sourceState.exists === false) {
        renameLogger.error(
          "items.rename.source-missing",
          "El rename fallo porque la ruta origen desaparecio durante la operacion.",
          {
            operation,
            itemId,
            from,
            to,
            sourceKind,
            attempt: attemptNumber,
            maxAttempts,
            errorCode,
            sourceState,
            destinationState,
          },
        );
        throw buildMissingSourceError(from);
      }

      if (!isRetriableRenameError(error) || attempt >= effectiveRetryDelaysMs.length) {
        renameLogger.error(
          "items.rename.failed",
          "El rename filesystem fallo y no se pudo recuperar.",
          {
            operation,
            itemId,
            from,
            to,
            sourceKind,
            attempt: attemptNumber,
            maxAttempts,
            errorCode,
            errorMessage: error instanceof Error ? error.message : String(error),
            sourceState,
            destinationState,
          },
        );
        throw error;
      }

      const delayMs = effectiveRetryDelaysMs[attempt];
      renameLogger.warn(
        "items.rename.retry",
        "El rename filesystem devolvio un lock transitorio; se reintentara.",
        {
          operation,
          itemId,
          from,
          to,
          sourceKind,
          attempt: attemptNumber,
          maxAttempts,
          delayMs,
          errorCode,
          errorMessage: error instanceof Error ? error.message : String(error),
          sourceState,
          destinationState,
        },
      );
      await wait(delayMs);
    }
  }
}
