export type IpcContractDirection = "invoke" | "send" | "event";
export type IpcContractScope = "host" | "vault" | "plugin" | "development";
export type IpcTimeoutClass = "control" | "io" | "long" | "interactive";

export type JsonSchema = boolean | Record<string, unknown>;

export interface IpcContractDefinition {
  id: string;
  key: string;
  wireChannel: string;
  owner: string;
  namespace: string;
  direction: IpcContractDirection;
  scope: IpcContractScope;
  timeoutClass: IpcTimeoutClass;
  timeoutMs: number | null;
  requestSchema: JsonSchema;
  responseSchema: JsonSchema;
}

export interface DefineIpcContractInput {
  key: string;
  owner?: string;
  direction?: IpcContractDirection;
  scope?: IpcContractScope;
  timeoutClass?: IpcTimeoutClass;
  requestSchema?: JsonSchema;
  responseSchema?: JsonSchema;
}

export const IPC_TIMEOUTS: Record<IpcTimeoutClass, number | null> = {
  control: 10_000,
  io: 30_000,
  long: 120_000,
  interactive: null,
};

const VAULT_SCOPED_NAMESPACES = new Set([
  "concepts",
  "items",
  "markdown",
  "markdown-links",
  "metadata",
  "preview",
  "search",
  "state",
  "trash",
  "vault",
  "vaultManager",
  "views",
]);

const IO_NAMESPACES = new Set([
  "dialog",
  "items",
  "markdown",
  "metadata",
  "preview",
  "trash",
  "vault",
  "vaultManager",
  "views",
]);

const LONG_OPERATION_PATTERN = /(reindex|rescan|import|export|install|update|reload|clear-data)/i;
const INTERACTIVE_OPERATION_PATTERN = /(choose|dialog|open-directory|open-image-file|open-media-file)/i;

function splitContractKey(key: string) {
  const normalizedKey = String(key || "").trim();
  const separatorIndex = normalizedKey.indexOf(":");

  if (separatorIndex < 0) {
    return {
      namespace: "legacy",
      operation: normalizedKey,
    };
  }

  return {
    namespace: normalizedKey.slice(0, separatorIndex),
    operation: normalizedKey.slice(separatorIndex + 1),
  };
}

function toIdentifierSegment(value: string) {
  return String(value || "")
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .toLowerCase();
}

export function inferIpcContractScope(key: string): IpcContractScope {
  const { namespace } = splitContractKey(key);

  if (namespace.startsWith("dev-") || namespace.startsWith("nexus:dev")) {
    return "development";
  }

  if (VAULT_SCOPED_NAMESPACES.has(namespace) || key.startsWith("nexus:files:")) {
    return "vault";
  }

  return "host";
}

export function inferIpcTimeoutClass(key: string): IpcTimeoutClass {
  const { namespace, operation } = splitContractKey(key);

  if (INTERACTIVE_OPERATION_PATTERN.test(key)) {
    return "interactive";
  }

  if (LONG_OPERATION_PATTERN.test(operation)) {
    return "long";
  }

  if (IO_NAMESPACES.has(namespace) || key.startsWith("nexus:files:")) {
    return "io";
  }

  return "control";
}

export function getCoreIpcContractId(key: string) {
  const { namespace, operation } = splitContractKey(key);
  return `core.${toIdentifierSegment(namespace)}.${toIdentifierSegment(operation)}`;
}

export function getPluginIpcContractId(pluginId: string, operation: string) {
  return `plugin.${toIdentifierSegment(pluginId)}.${toIdentifierSegment(operation)}`;
}

export function getIpcWireChannel(contractId: string) {
  return `nexus:v2:${contractId}`;
}

export function defineIpcContract(input: DefineIpcContractInput): IpcContractDefinition {
  const key = String(input.key || "").trim();
  if (!key) {
    throw new Error("IPC_CONTRACT_KEY_REQUIRED");
  }

  const pluginMatch = /^plugin:([^:]+):(.+)$/.exec(key);
  const id = pluginMatch
    ? getPluginIpcContractId(pluginMatch[1], pluginMatch[2])
    : getCoreIpcContractId(key);
  const namespace = pluginMatch ? `plugin.${toIdentifierSegment(pluginMatch[1])}` : splitContractKey(key).namespace;
  const timeoutClass = input.timeoutClass || inferIpcTimeoutClass(key);

  return Object.freeze({
    id,
    key,
    wireChannel: getIpcWireChannel(id),
    owner: input.owner || (pluginMatch ? pluginMatch[1] : `core.${namespace}`),
    namespace,
    direction: input.direction || "invoke",
    scope: input.scope || (pluginMatch ? "plugin" : inferIpcContractScope(key)),
    timeoutClass,
    timeoutMs: IPC_TIMEOUTS[timeoutClass],
    requestSchema: input.requestSchema || { type: "array" },
    responseSchema: input.responseSchema ?? true,
  });
}

export function getPluginContractKey(pluginId: string, operation: string) {
  const normalizedPluginId = String(pluginId || "").trim();
  const normalizedOperation = String(operation || "").trim();
  if (!normalizedPluginId || !normalizedOperation || normalizedOperation.includes(":")) {
    throw new Error("PLUGIN_IPC_OPERATION_INVALID");
  }
  return `plugin:${normalizedPluginId}:${normalizedOperation}`;
}

export function getPluginOperationFromLegacyChannel(pluginId: string, channel: string) {
  const normalizedPluginId = String(pluginId || "").trim();
  const normalizedChannel = String(channel || "").trim();
  const knownPrefixes = [
    `${normalizedPluginId.replace(/^nexus\./, "")}:`,
    `${normalizedPluginId}:`,
    normalizedPluginId === "nexus.chat" ? "chatbot:" : "",
    normalizedPluginId === "nexus.musica" ? "audio:" : "",
  ].filter(Boolean);

  for (const prefix of knownPrefixes) {
    if (normalizedChannel.startsWith(prefix)) {
      return normalizedChannel.slice(prefix.length).trim();
    }
  }

  const separatorIndex = normalizedChannel.lastIndexOf(":");
  return separatorIndex >= 0
    ? normalizedChannel.slice(separatorIndex + 1).trim()
    : normalizedChannel;
}
