import { Ajv, type ValidateFunction } from "ajv";
import type {
  IpcMain,
  IpcMainEvent,
  IpcMainInvokeEvent,
  WebContents,
} from "electron";
import {
  defineIpcContract,
  type DefineIpcContractInput,
  type IpcContractDefinition,
} from "../shared/ipc-contracts.js";
import { getCurrentVaultRuntimeSession } from "../backend/vault-runtime/session.js";

export interface IpcContractFailure {
  ok: false;
  error: {
    code: string;
    message: string;
    retryable: boolean;
  };
}

export interface IpcContractSuccess<T = unknown> {
  ok: true;
  data: T;
}

export type IpcContractResult<T = unknown> = IpcContractSuccess<T> | IpcContractFailure;

interface RegisteredContract {
  definition: IpcContractDefinition;
  validateRequest: ValidateFunction;
  validateResponse: ValidateFunction;
}

const ajv = new Ajv({ allErrors: true, strict: false, allowUnionTypes: true });
const contractByKey = new Map<string, RegisteredContract>();
const contractById = new Map<string, RegisteredContract>();
const requestContextByEvent = new WeakMap<object, IpcRequestContext>();

export interface IpcRequestContext {
  signal: AbortSignal;
  generation: number | null;
  onCleanup(cleanup: () => void | Promise<void>): void;
}

function createFailure(code: string, message: string, retryable = false): IpcContractFailure {
  return {
    ok: false,
    error: { code, message, retryable },
  };
}

function sanitizeError(error: unknown) {
  if (error instanceof Error) {
    return (error.message || "La operacion IPC fallo.")
      .replace(/(?:[a-zA-Z]:[\\/]|\\\\)[^\s"']+/g, "[ruta privada]");
  }
  return "La operacion IPC fallo.";
}

export function getIpcRequestContext(event: IpcMainInvokeEvent) {
  const context = requestContextByEvent.get(event);
  if (!context) {
    throw new Error("IPC_REQUEST_CONTEXT_UNAVAILABLE");
  }
  return context;
}

function isTrustedSender(event: IpcMainInvokeEvent | IpcMainEvent) {
  const frame = event.senderFrame;
  if (!frame || frame !== frame.top) {
    return false;
  }

  const rawUrl = frame.url || event.sender.getURL();
  try {
    const parsed = new URL(rawUrl);
    if (parsed.protocol === "file:" || parsed.protocol === "data:") {
      return true;
    }
    return (
      (parsed.protocol === "http:" || parsed.protocol === "https:")
      && (parsed.hostname === "127.0.0.1" || parsed.hostname === "localhost")
    );
  } catch {
    return false;
  }
}

export function registerIpcContract(input: DefineIpcContractInput) {
  const definition = defineIpcContract(input);
  const existingById = contractById.get(definition.id);
  if (existingById && existingById.definition.key !== definition.key) {
    throw new Error(`IPC_CONTRACT_COLLISION:${definition.id}`);
  }

  const existing = contractByKey.get(definition.key);
  if (existing) {
    return existing.definition;
  }

  const registered: RegisteredContract = {
    definition,
    validateRequest: ajv.compile(definition.requestSchema),
    validateResponse: ajv.compile(definition.responseSchema),
  };
  contractByKey.set(definition.key, registered);
  contractById.set(definition.id, registered);
  return definition;
}

export function getRegisteredIpcContracts() {
  return [...contractById.values()]
    .map(({ definition }) => definition)
    .sort((left, right) => left.id.localeCompare(right.id));
}

export function resetIpcContractCatalogForTests() {
  contractByKey.clear();
  contractById.clear();
}

export function sendContractIpcEvent(
  target: Pick<WebContents, "send">,
  key: string,
  ...args: unknown[]
) {
  const registered = contractByKey.get(key);
  const contract = registered?.definition || registerIpcContract({
    key,
    direction: "event",
    timeoutClass: "control",
  });
  const validators = contractByKey.get(key)!;
  if (!validators.validateRequest(args)) {
    throw new Error(`IPC_EVENT_INVALID_PAYLOAD:${contract.id}`);
  }
  target.send(contract.wireChannel, ...args);
}

async function runWithDeadline<T>(
  contract: IpcContractDefinition,
  task: Promise<T>,
  abortController: AbortController,
  cleanups: Array<() => void | Promise<void>>,
): Promise<T> {
  if (contract.timeoutMs == null) {
    return task;
  }

  let timeoutId: ReturnType<typeof setTimeout> | null = null;
  const timeout = new Promise<never>((_resolve, reject) => {
    timeoutId = setTimeout(() => {
      abortController.abort(new Error("IPC_TIMEOUT"));
      for (const cleanup of cleanups.splice(0)) {
        void Promise.resolve().then(cleanup).catch(() => undefined);
      }
      const error = new Error(`La operacion ${contract.id} excedio ${contract.timeoutMs} ms.`);
      error.name = "IpcContractTimeoutError";
      reject(error);
    }, contract.timeoutMs);
    timeoutId.unref?.();
  });

  try {
    return await Promise.race([task, timeout]);
  } finally {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
  }
}

export function createContractIpcMain(realIpcMain: IpcMain): IpcMain {
  return new Proxy(realIpcMain, {
    get(target, property, receiver) {
      if (property === "handle") {
        return (
          key: string,
          listener: (event: IpcMainInvokeEvent, ...args: unknown[]) => unknown,
        ) => {
          const registered = contractByKey.get(key);
          const contract = registered?.definition || registerIpcContract({ key });
          const validators = contractByKey.get(key)!;

          return target.handle(contract.wireChannel, async (event, ...args) => {
            if (!isTrustedSender(event)) {
              return createFailure("IPC_SENDER_REJECTED", "El origen de la solicitud no esta autorizado.");
            }
            if (!validators.validateRequest(args)) {
              return createFailure("IPC_INVALID_PAYLOAD", "La solicitud no cumple el contrato IPC.");
            }

            const capturedSession = contract.scope === "vault" || contract.scope === "plugin"
              ? getCurrentVaultRuntimeSession()
              : null;
            if ((contract.scope === "vault" || contract.scope === "plugin") && !capturedSession?.acceptingWork) {
              return createFailure("VAULT_RUNTIME_UNAVAILABLE", "El vault activo no admite trabajo nuevo.", true);
            }

            const abortController = new AbortController();
            const cleanups: Array<() => void | Promise<void>> = [];
            requestContextByEvent.set(event, {
              signal: abortController.signal,
              generation: capturedSession?.generation ?? null,
              onCleanup(cleanup) {
                if (typeof cleanup === "function") cleanups.push(cleanup);
              },
            });

            try {
              const data = await runWithDeadline(
                contract,
                Promise.resolve().then(() => listener(event, ...args)),
                abortController,
                cleanups,
              );
              if (capturedSession && !capturedSession.canPublish()) {
                return createFailure("VAULT_GENERATION_STALE", "La operacion pertenece a una generacion anterior del vault.", true);
              }
              if (!validators.validateResponse(data)) {
                return createFailure("IPC_INVALID_RESPONSE", "La respuesta no cumple el contrato IPC.");
              }
              return { ok: true, data } satisfies IpcContractSuccess;
            } catch (error) {
              const timedOut = error instanceof Error && error.name === "IpcContractTimeoutError";
              return createFailure(
                timedOut ? "IPC_TIMEOUT" : "IPC_HANDLER_FAILED",
                sanitizeError(error),
                timedOut,
              );
            } finally {
              requestContextByEvent.delete(event);
            }
          });
        };
      }

      if (property === "on") {
        return (
          key: string,
          listener: (event: IpcMainEvent, ...args: unknown[]) => void,
        ) => {
          const registered = contractByKey.get(key);
          const contract = registered?.definition || registerIpcContract({
            key,
            direction: "send",
            timeoutClass: "control",
          });
          const validators = contractByKey.get(key)!;
          return target.on(contract.wireChannel, (event, ...args) => {
            if (!isTrustedSender(event) || !validators.validateRequest(args)) {
              return;
            }
            listener(event, ...args);
          });
        };
      }

      if (property === "removeHandler") {
        return (key: string) => {
          const contract = contractByKey.get(key)?.definition || defineIpcContract({ key });
          return target.removeHandler(contract.wireChannel);
        };
      }

      return Reflect.get(target, property, receiver);
    },
  });
}
